class Clock extends Date { constructor(...args){super(...(args.length?args:[fixedNow]));} static now(){return fixedNow;} }
class TS { constructor(ms){this.ms=ms;} static now(){return new TS(fixedNow);} static fromMillis(ms){return new TS(ms);} toMillis(){return this.ms;} toDate(){return new Date(this.ms);} }
