 await test('manual existing action validates strict owner fields and forwards exact company actor without a caller queue',async()=>{const e=manualEnvironment();await e.adapter.executeCaseListImport(company,'commit',actor,owner);const api=manualAdminAPI(e),data={action:'select-case-list-manual-monthly',jobId,observationHash:manualObservation(e).observationHash,expectedJobRevision:1,expectedSourceRevision:source(e).sourceRevision,clientNameUpConfirmed:true,manualConfirmation:{confirmedFields:{arrival:true,execution:true,headcount:true,dateMode:true,payOffer:true},payOffer:{dailyWageJPY:10000,travelExpenses:'全額支給',communicationExpenses:'全額支給'}}};const result=await api.acknowledgeSheetWriteIssue({auth:{uid:actor,token:owner},data});assert.equal(result.status,'OWNER_TRANSFER_SELECTED');assert.equal(api.calls.length,1);assert.equal(api.calls[0][0],company);assert.equal(api.calls[0][1],actor);assert.equal(api.calls[0][2],owner);assert.deepEqual(JSON.parse(JSON.stringify(api.calls[0][3])),data);for(const bad of [{...data,clientNameUpConfirmed:false},{...data,queueId:'not-accepted'},{...data,manualConfirmation:{...data.manualConfirmation,confirmedFields:{...data.manualConfirmation.confirmedFields,vacancy:true}}}])await assert.rejects(()=>api.acknowledgeSheetWriteIssue({auth:{uid:actor,token:owner},data:bad}));assert.equal(api.calls.length,1);e.state.operationalReject=true;await assert.rejects(()=>api.acknowledgeSheetWriteIssue({auth:{uid:actor,token:owner},data}));assert.equal(api.calls.length,1);});

 function cancelManualPending(e){const job=e.dbState.state.get('jobs/'+jobId);job.status='cancelled';job.cancelled=true;job.sourceCancellationClosed=true;job.cancelledBy=actor;job.cancellationReason='合成取消';job.revision++;job.assignmentSheetWrite=null;job.cancellationSheetWrite={operation:'job.cancel.v2',queueId:'manual-cancel-1',identity:sheetCore.cancellationSheetWriteIdentity(job),sourceAckVersion:1,sourceAckPending:true,sourceAckRequestedAtMs:fixedNow-100,sourceAckJobRevision:job.revision};e.dbState.state.set('sheetSyncQueue/manual-cancel-1',{companyId:company,jobId,operation:'job.cancel.v2',actorUid:actor,idempotencyKey:'job.cancel.v2:'+jobId+':manual-cancel-1',updates:{cancelled:true,cancellationReason:'合成取消'}});}
 function blankCancelledManualSource(e){e.f.rows[1][63]={userEnteredValue:{boolValue:true},effectiveValue:{boolValue:true}};e.f.rows[1][2]={};}
 await test('actual Source import fresh cancelled blank readback releases only the pending manual owned daylock',async()=>{const e=manualEnvironment();await e.adapter.executeCaseListImport(company,'commit',actor,owner);cancelManualPending(e);blankCancelledManualSource(e);await e.adapter.executeCaseListImport(company,'commit',actor,owner);const job=e.dbState.state.get('jobs/'+jobId),lock=e.dbState.state.get('staffDayLocks/'+company+'_manual-staff_2026-11-20');assert.equal(job.cancellationSheetWrite.sourceAckPending,false);assert.equal(job.cancellationSheetWrite.sourceAckProof.originalRevision,2);assert.equal(job.status,'cancelled');assert.equal(job.assignedStaffId,'manual-staff');assert.equal(job.recruitmentStopped,true);assert.equal(lock.active,false);assert.equal(e.dbState.writes.some(w=>w.path.startsWith('sheetSyncQueue/')&&w.kind!=='read'),false);});
 for(const [label,a]of [['checked',{userEnteredValue:{boolValue:true},effectiveValue:{boolValue:true}}],['unchecked',{userEnteredValue:{boolValue:false},effectiveValue:{boolValue:false}}],['unrelated literal',str('旧管理欄')]])await test('Source cancellation ACK uses canonical BL with A '+label,async()=>{const e=manualEnvironment();await e.adapter.executeCaseListImport(company,'commit',actor,owner);cancelManualPending(e);blankCancelledManualSource(e);e.f.rows[1][0]=a;await e.adapter.executeCaseListImport(company,'commit',actor,owner);const job=e.dbState.state.get('jobs/'+jobId);assert.equal(job.cancellationSheetWrite.sourceAckPending,false);assert.equal(e.dbState.state.get('staffDayLocks/'+company+'_manual-staff_2026-11-20').active,false);assert.equal(job.publishable,false);assert.equal(job.recruitmentStopped,true);assert.equal(job.caseId,caseId);assert.equal(job.assignedStaffId,'manual-staff');});
 for(const [label,bl]of [['false',{userEnteredValue:{boolValue:false},effectiveValue:{boolValue:false}}],['missing',{}],['formula',{userEnteredValue:{formulaValue:'=TRUE()'},effectiveValue:{boolValue:true}}],['inconsistent native value',{userEnteredValue:{boolValue:true},effectiveValue:{boolValue:false}}]])await test('A checked cannot acknowledge Source cancellation with BL '+label,async()=>{const e=manualEnvironment();await e.adapter.executeCaseListImport(company,'commit',actor,owner);cancelManualPending(e);blankCancelledManualSource(e);e.f.rows[1][0]={userEnteredValue:{boolValue:true},effectiveValue:{boolValue:true}};e.f.rows[1][63]=bl;const before=clone(e.dbState.state.get('jobs/'+jobId).caseListSource);await e.adapter.executeCaseListImport(company,'commit',actor,owner);const job=e.dbState.state.get('jobs/'+jobId);assert.equal(job.cancellationSheetWrite.sourceAckPending,true);assert.equal(job.revision,2);assert.deepEqual(job.caseListSource,before);assert.equal(e.dbState.state.get('staffDayLocks/'+company+'_manual-staff_2026-11-20').active,true);assert.equal(job.status,'cancelled');assert.equal(job.cancelled,true);});
 for(const [reason,change]of [['stale read',e=>e.dbState.state.get('jobs/'+jobId).cancellationSheetWrite.sourceAckRequestedAtMs=fixedNow+100],['name retained',e=>e.f.rows[1][2]=str('手入力合成担当')],['foreign lock',e=>e.dbState.state.get('staffDayLocks/'+company+'_manual-staff_2026-11-20').jobId='other-job'],['queue changed',e=>e.dbState.state.get('sheetSyncQueue/manual-cancel-1').actorUid='foreign']])await test('Source manual cancel readback holds '+reason+' without releasing or changing original cancel revision',async()=>{const e=manualEnvironment();await e.adapter.executeCaseListImport(company,'commit',actor,owner);cancelManualPending(e);blankCancelledManualSource(e);change(e);const before=e.dbState.state.get('jobs/'+jobId).caseListSource.sourceRevision;await e.adapter.executeCaseListImport(company,'commit',actor,owner);const job=e.dbState.state.get('jobs/'+jobId);assert.equal(job.cancellationSheetWrite.sourceAckPending,true);assert.equal(job.revision,2);assert.equal(job.caseListSource.sourceRevision,before);assert.equal(e.dbState.state.get('staffDayLocks/'+company+'_manual-staff_2026-11-20').active,true);assert.equal(job.status,'cancelled');});
